import{_ as s,o as e,c as n,aO as i}from"./chunks/framework.vjUPZZJn.js";const u=JSON.parse('{"title":"Linux 多版本程序管理：update-alternatives","description":"","frontmatter":{"date":"2026-11-09T03:15:00.000Z","title":"Linux 多版本程序管理：update-alternatives","source":"[[1-知识/工具/Linux环境/linux 软件多版本管理]]","tags":["工具","教程手册","Linux","环境配置"],"categories":["工具"],"permalink":"/pages/742a87"},"headers":[],"relativePath":"工具/Linux 多版本程序管理：update-alternatives.md","filePath":"工具/Linux 多版本程序管理：update-alternatives.md","lastUpdated":1794223026000}'),t={name:"工具/Linux 多版本程序管理：update-alternatives.md"};function p(l,a,r,d,c,h){return e(),n("div",null,[...a[0]||(a[0]=[i(`<h1 id="linux-多版本程序管理-update-alternatives" tabindex="-1">Linux 多版本程序管理：update-alternatives <a class="header-anchor" href="#linux-多版本程序管理-update-alternatives" aria-label="Permalink to &quot;Linux 多版本程序管理：update-alternatives&quot;">​</a></h1> <p>同一台 Linux 机器上，不同项目对同一程序的要求可能不同：老工程要 cmake 3.16，新工程要 3.20。Debian 系发行版自带的 <code>update-alternatives</code> 就是为此设计的——把多个版本的同一程序注册到一个统一的命令名下，按优先级决定默认版本，一条命令交互切换。本文以管理两个 cmake 版本为例，覆盖注册、切换、验证的完整流程。适合需要在系统级共存多个工具版本的开发者。</p> <h2 id="工作原理" tabindex="-1">工作原理 <a class="header-anchor" href="#工作原理" aria-label="Permalink to &quot;工作原理&quot;">​</a></h2> <p><code>update-alternatives</code> 维护一条两级符号链接链：<code>/usr/bin/cmake</code> 指向 <code>/etc/alternatives/cmake</code>，后者再指向实际程序路径（如 <code>~/opt/cmake-3.20.0/bin/cmake</code>）。切换版本只是重指这条链，所有通过 <code>/usr/bin/cmake</code> 调用的程序（包括 <code>ctest</code>、<code>cpack</code> 等同目录工具）自动跟随，系统级生效、对所有用户可用。</p> <h2 id="注册多个版本" tabindex="-1">注册多个版本 <a class="header-anchor" href="#注册多个版本" aria-label="Permalink to &quot;注册多个版本&quot;">​</a></h2> <div class="language-bash vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> update-alternatives</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --install</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /usr/bin/cmake</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> cmake</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ~/opt/cmake-3.16.3/bin/cmake</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 20</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> update-alternatives</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --install</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /usr/bin/cmake</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> cmake</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ~/opt/cmake-3.20.0/bin/cmake</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 10</span></span></code></pre> <div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br></div></div><p>四个参数依次是：链接路径（统一的命令入口）、名称（标识这组备选）、实际程序路径、优先级。<strong>优先级数字越大越优先</strong>，自动模式下系统选择优先级最高的版本——上面的例子里默认版本是 3.16.3。</p> <h2 id="切换版本" tabindex="-1">切换版本 <a class="header-anchor" href="#切换版本" aria-label="Permalink to &quot;切换版本&quot;">​</a></h2> <div class="language-bash vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> update-alternatives</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --config</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> cmake</span></span></code></pre> <div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p>交互式选择：</p> <div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>There are 2 choices for the alternative cmake (providing /usr/bin/cmake).</span></span>
<span class="line"><span></span></span>
<span class="line"><span>  Selection    Path                                   Priority   Status</span></span>
<span class="line"><span>------------------------------------------------------------</span></span>
<span class="line"><span>* 0            /home/user/opt/cmake-3.16.3/bin/cmake   20        auto mode</span></span>
<span class="line"><span>  1            /home/user/opt/cmake-3.16.3/bin/cmake   20        manual mode</span></span>
<span class="line"><span>  2            /home/user/opt/cmake-3.20.0/bin/cmake   10        manual mode</span></span>
<span class="line"><span></span></span>
<span class="line"><span>Press &lt;enter&gt; to keep the current choice[*], or type selection number:</span></span></code></pre> <div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br><span class="line-number">9</span><br></div></div><p>输入编号回车即可切换。这里有两种模式值得区分：</p> <ul><li><strong>auto mode</strong>（编号 0）：跟随优先级自动选择，注册新版本后默认指向可能变化；</li> <li><strong>manual mode</strong>（编号 1、2）：固定使用选定版本，不再随优先级变动。</li></ul> <p>直接回车保持当前选择不变。</p> <h2 id="验证" tabindex="-1">验证 <a class="header-anchor" href="#验证" aria-label="Permalink to &quot;验证&quot;">​</a></h2> <div class="language-bash vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">cmake</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --version</span></span></code></pre> <div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p>输出即当前选中的版本。切换后无需重新登录或刷新缓存。</p> <h2 id="适用边界" tabindex="-1">适用边界 <a class="header-anchor" href="#适用边界" aria-label="Permalink to &quot;适用边界&quot;">​</a></h2> <p><code>update-alternatives</code> 适合 cmake、gcc、python 这类「一个命令入口、多版本共存」的系统程序。它的局限同样明显：按命令全局切换，不能按项目自动选择版本。如果管理的是 Node.js、Python 这类有专用版本管理器（nvm、Volta、pyenv 等）的运行时，且需要进入项目目录自动切换，用专用工具更合适；系统级、手动切换的场景，<code>update-alternatives</code> 足够且零依赖。</p>`,33)])])}const k=s(t,[["render",p]]);export{u as __pageData,k as default};
